"""Render a search directory as a portable, offline comparison report."""
import argparse,json
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('run',type=Path);p.add_argument('--html',type=Path);a=p.parse_args()
rows=[json.loads(line) for line in (a.run/'trials.jsonl').read_text(encoding='utf-8-sig').splitlines() if line]
def read(name,default):
 path=a.run/name
 return json.loads(path.read_text(encoding='utf-8-sig')) if path.exists() else default
payload={'rows':rows,'summary':read('summary.json',{}),'settings':read('settings.json',{}),'pareto':read('pareto.json',[]),'replay':read('best-replay.json',None)}
html=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Factory · Build-order search</title><style>
:root{color-scheme:dark;--bg:#10171c;--card:#1b252c;--line:#354550;--text:#edf2ee;--muted:#a2b1b8;--accent:#a9d88d;--gold:#edbd6e}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui}main{max-width:1500px;margin:auto;padding:32px}h1{font-size:32px;margin:6px 0}h2{font-size:20px}h3{font-size:15px}.eyebrow{color:var(--accent);letter-spacing:2px;font-size:11px;text-transform:uppercase}p{color:var(--muted);line-height:1.6;max-width:1100px}a{color:var(--accent)}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:28px 0}.card,section{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:20px}.card small{display:block;color:var(--muted)}.card strong{display:block;font-size:30px;margin-top:10px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:20px}svg{width:100%;height:300px}svg text{fill:var(--muted);font:12px system-ui}circle{cursor:pointer}table{border-collapse:collapse;width:100%;font-size:12px}td,th{padding:10px 8px;border-bottom:1px solid var(--line);text-align:right}td:first-child,th:first-child{text-align:left}th{color:var(--muted);font-weight:500}button,select{background:#253740;border:1px solid var(--line);border-radius:5px;color:var(--text);padding:7px;cursor:pointer}button:hover{border-color:var(--accent)}.scroll{max-height:390px;overflow:auto}.warn{color:var(--gold)}pre{white-space:pre-wrap;color:var(--muted);font:12px/1.7 system-ui}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.selected{background:#30423a}#timeline{max-height:480px;overflow:auto}footer{color:var(--muted);margin:24px 0;font-size:12px}@media(max-width:800px){.grid{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr}main{padding:16px}}
</style><main><div class="eyebrow">Economy lab / Chronological search</div><h1>Investment → production → first flight.</h1><p>Every candidate starts with the game's landing inventory. Construction, research and project payments come from its evolving factory. Player placement time is zero. Compare completion time against extracted materials and electricity.</p><div class="metrics" id="metrics"></div><div class="grid"><section><h2>Speed has a resource cost</h2><p>Each dot is a completed Fighter. Green: no tested policy is better on time, electricity and total extracted raw units simultaneously. Click a dot to inspect its policy.</p><svg id="plot" viewBox="0 0 600 300" aria-label="Fighter time versus extracted raw units"></svg></section><section><h2>What this search can tell us</h2><p id="settings"></p><p>Search candidates are staged investment policies, with production assigned by a heuristic. The fastest result is a benchmark, not proof of optimal play. Sample percentiles describe this search population, not normal-player behavior.</p><p class="warn">Transport uses paid, powered T1 tiles with pooled input-throughput budgets and machine output limits. Shared cargo has no travel delay. Physical connections, mergers, storage routing and belt-layout feasibility are not solved.</p><p>Time, energy and raw extraction form a tradeoff frontier. Raw units are an unweighted sum, not a currency. Inspect individual materials in the detailed replay before balancing prices.</p></section></div><div class="grid"><section><div class="toolbar"><h2>Tested policies</h2><label>Sort <select id="sort"><option value="seconds">Fighter time</option><option value="energyPUHours">Electricity</option><option value="rawExtracted">Raw extraction</option><option value="capitalWaitSeconds">Funding wait</option></select></label><label><input id="frontier" type="checkbox"> Frontier only</label></div><div class="scroll"><table><thead><tr><th>Policy</th><th>Minutes</th><th>PU·h</th><th>Raw units</th><th>Funding wait</th></tr></thead><tbody id="trials"></tbody></table></div></section><section><div class="toolbar"><h2 id="policyTitle">Policy</h2><button id="download">Export policy JSON</button></div><p id="policyStats"></p><div class="scroll" id="policy"></div></section></div><section><h2>Best-time replay · actual purchase order and saving periods</h2><p>Funding wait measures time spent unable to afford the next queued building. Other production and research may continue during that wait; it is not additional elapsed time. Reclamation follows the game's refunds. Minute-by-minute inventory, queue shortfalls and machine-state totals are saved in best-replay.json.</p><div id="timeline"></div></section><footer>Reproducible seed and catalog snapshot saved alongside every run. To test balance changes, run the same seed, timestep and search budget against a candidate catalog. No live catalog changes are made by this tool.</footer></main><script>const DATA=__DATA__;
const $=id=>document.getElementById(id),num=x=>Number(x).toLocaleString(undefined,{maximumFractionDigits:1}),escape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const wins=DATA.rows.filter(r=>r.success).sort((a,b)=>a.seconds-b.seconds),frontier=new Set(DATA.pareto.map(r=>r.id));let selected=wins[0]||DATA.rows[0];
$('metrics').innerHTML=[['Policies tested',DATA.rows.length],['Completed Fighters',wins.length],['Best found',wins.length?num(wins[0].seconds/60)+' min':'None'],['Median successful sample',wins.length?num(wins[Math.floor(wins.length/2)].seconds/60)+' min':'—']].map(([label,value])=>`<div class="card"><small>${label}</small><strong>${value}</strong></div>`).join('');
$('settings').textContent=`Seed ${DATA.settings.seed}; ${DATA.settings.step}s simulation ticks; ${DATA.settings.workers} workers. ${DATA.rows.length-wins.length} failed policies are retained with reasons. Search changes counts, within-stage investment order, upgrade delays, reclamation, recipe priorities and parallel belt lanes.`;
function table(){let rows=DATA.rows.filter(r=>!$('frontier').checked||frontier.has(r.id)).sort((a,b)=>Number(b.success)-Number(a.success)||a[$('sort').value]-b[$('sort').value]);$('trials').innerHTML=rows.map(r=>`<tr class="${selected.id===r.id?'selected':''}"><td><button data-id="${r.id}">#${r.id}${frontier.has(r.id)?' •':''}</button></td><td>${r.success?num(r.seconds/60):'Failed'}</td><td>${num(r.energyPUHours)}</td><td>${num(r.rawExtracted)}</td><td>${num(r.capitalWaitSeconds/60)}m</td></tr>`).join('');}
function inspect(id){selected=DATA.rows.find(r=>r.id===id);$('policyTitle').textContent='Policy #'+id;$('policyStats').textContent=selected.success?`Fighter ${num(selected.seconds/60)} min · brownouts ${num(selected.brownoutSeconds/60)} min · ${selected.policy.lanes} T1 lanes per pool · ${selected.policy.reclaim?'reclaims replaced machines':'keeps old machines'}`:'Failure: '+selected.error;$('policy').innerHTML=selected.policy.stages.map((stage,i)=>`<h3>${i?'After research tier '+i:'Landing'}</h3><pre>${stage.filter(t=>t.count).map(t=>escape(t.spec)+' → '+t.count+' total').join('\n')}</pre>`).join('');table();}
if(wins.length){let maxX=Math.max(...wins.map(r=>r.rawExtracted))*1.05,maxY=Math.max(...wins.map(r=>r.seconds/60))*1.08;
$('plot').innerHTML=`<path d="M55 15V260H580" fill="none" stroke="#60717a"/><text x="220" y="294">Raw units extracted →</text><text x="8" y="14">Minutes</text>`+[0,.25,.5,.75,1].map(t=>`<text x="5" y="${264-t*235}">${num(t*maxY)}</text><text x="${55+t*520}" y="278">${num(t*maxX)}</text>`).join('')+wins.map(r=>`<circle data-id="${r.id}" cx="${55+r.rawExtracted/maxX*520}" cy="${260-r.seconds/60/maxY*235}" r="5" fill="${frontier.has(r.id)?'#a9d88d':'#819ba9'}" opacity=".8"><title>#${r.id}: ${num(r.seconds/60)} min, ${num(r.rawExtracted)} raw</title></circle>`).join('');}
$('timeline').innerHTML=DATA.replay?'<table><thead><tr><th>At minute</th><th>Stage</th><th>Purchase / transition</th><th>Saving wait</th></tr></thead><tbody>'+DATA.replay.events.filter(e=>e.kind!=='build').map(e=>`<tr><td>${num(e.time/60)}</td><td>${escape(e.stage)}</td><td>${escape(e.kind+' · '+e.detail)}</td><td>${e.waitSeconds===undefined?'—':num(e.waitSeconds/60)+' min'}</td></tr>`).join('')+'</tbody></table>':'No successful replay.';
document.addEventListener('click',e=>{const node=e.target.closest('[data-id]');if(node)inspect(Number(node.dataset.id));});$('sort').onchange=table;$('frontier').onchange=table;$('download').onclick=()=>{const blob=new Blob([JSON.stringify({...selected.policy,trace:true},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='policy-'+selected.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};if(selected)inspect(selected.id);
</script></html>'''
html=html.replace('__DATA__',json.dumps(payload,separators=(',',':')).replace('<','\\u003c'))
output=a.html or a.run/'report.html';output.write_text(html,encoding='utf-8');print(output.resolve())
